Natural Language Question: Show the stadium name and capacity with most number of concerts in year 2014 or after.

execution_result.cleaned_query:
SELECT ?stadium_name ?stadium_capacity
WHERE {
  ?stadium :stadium\#stadium_id ?stadium_id ;
             :stadium\#name ?stadium_name ;
             :stadium\#capacity ?stadium_capacity .
  {
    SELECT ?stadium_id (COUNT(?concert) AS ?concert_count)
    WHERE {
      ?concert :concert\#ref-stadium_id ?stadium_id ;
                 :concert\#year ?year .
      FILTER(?year >= "2014")
    }
    GROUP BY ?stadium_id
    ORDER BY DESC(?concert_count)
    LIMIT 1
  }
  FILTER(?stadium_id = ?stadium_id)
}

